class Buffer {
    int* data;
public:
    Buffer(size_t size) : data(new int[size]) {} // Resource Acquisition
    ~Buffer() { delete[] data; }                 // Resource Release (Destruction)
    Buffer(const Buffer&) = delete;              // Rule of Five safety
};

// Standard library RAII (Preferred Method)
void safe_function() {
    auto p = std::make_unique<Connection>(); // RAII object constructed
    // If an exception occurs during subsequent operations,
    // p is destroyed during stack unwinding, guaranteeing release.
}

// RAII for synchronization
std::mutex mtx;
void protected_call() {
    std::lock_guard<std::mutex> lock(mtx);
    // Mutex automatically released (unlocked) upon scope exit
    // (return or exception throw).
}
